  function runLinuxCmd(key, btn) {
    const d = LINUX_CMDS[key];
    if (!d) return;
    const runsArea = document.getElementById('ldRunsArea');
    if (d.runs && d.runs.length) {
      renderCmdRuns(d.runs, runsArea);
    } else {
      // legacy shape — single cmd/output pair, not yet migrated to runs:[]
      const lines = d.cmd.split('\n');
      let extra = '';
      if (lines.length > 1) {
        extra = lines.slice(1).map(l => '<span class="ld-prompt">devops@server:~$</span> ' + l).join('\n') + '\n';
      }
      renderCmdRuns([{ cmd: lines[0], output: extra + d.output }], runsArea);
    }
    document.getElementById('ldSyntax').innerHTML = d.syntax || (d.runs ? d.runs[0].cmd.split('\n')[0] : d.cmd.split('\n')[0]);
    document.getElementById('ldDoes').innerHTML = d.does;
    document.getElementById('ldWhere').innerHTML = d.where;
    const bdList = document.getElementById('ldBreakdownList');
    if (bdList) {
      bdList.innerHTML = (d.breakdown && d.breakdown.length)
        ? d.breakdown.map(b => `<div class="sl-breakdown-item"><span class="sl-breakdown-term">${b.term}</span><span class="sl-breakdown-desc">${b.desc}</span></div>`).join('')
        : '<span class="dim">No further breakdown needed for this one.</span>';
    }
    const whyEl = document.getElementById('ldWhyUseful');
    if (whyEl) whyEl.innerHTML = d.whyUseful || '<span class="dim">—</span>';
    document.querySelectorAll('.ld-pill').forEach(p => p.classList.remove('active'));
    if (btn) btn.classList.add('active');
  }


  /* ══════════════════════════════════════════════════════════════════
     REUSABLE QUIZ GAME ENGINE
     ══════════════════════════════════════════════════════════════════
     Built once here for the Linux for DevOps tab, designed to be dropped
     into ANY other tab with zero changes to the functions below.

     HOW TO ADD THIS TO ANOTHER TAB (e.g. "docker"):
     1. Copy the entire HTML block that starts with
          <div class="section-title">🎮 Test Yourself ...
        and ends with the closing </div> of class="quiz-game", and paste
        it near the bottom of the target tab's panel.
     2. Find-and-replace the id 'quiz-linuxdevops' → something unique,
        e.g. 'quiz-docker', in that pasted HTML block (3 places: the
        container id, and the two onclick calls that pass it as rootId).
     3. Down here in the JS, define two new arrays with unique names —
        e.g. DOCKER_QUIZ_JOKES (5 strings) and DOCKER_QUIZ_QUESTIONS
        (50 objects, same shape as LINUXDEVOPS_QUIZ_QUESTIONS below:
        { q: "...", options: ["A","B","C","D"], correct: 0, why: "..." }).
     4. Update that tab's Play button onclick to:
          quizStart('quiz-docker', DOCKER_QUIZ_JOKES, DOCKER_QUIZ_QUESTIONS)
     5. Update its "Play Again" button onclick to: quizReset('quiz-docker')

     That's the entire integration. quizStart / quizNext / quizAnswer /
     quizQuit / quizReset below are 100% generic — they never hardcode
     "linux" or any tab name. They always work off whichever rootId was
     passed to quizStart(), stored in QUIZ_STATE.rootId, and they always
     look up elements by class name *inside* that root — so two different
     tabs' quiz widgets never collide, even though only one can be
     "playing" at a time (QUIZ_STATE is a single shared variable).
     ══════════════════════════════════════════════════════════════════ */

  const LINUXDEVOPS_QUIZ_JOKES = [
    `There are only 10 types of people in the world: those who understand binary, and those who don't.`,
    `Why did the Linux sysadmin get locked out of the party? He forgot to chmod +x the invitation.`,
    `sudo rm -rf / is the closest thing Linux has to a "delete my browser history" button. Please, never actually press it.`,
    `A user asked how to exit vim. Nobody has heard from them since 2019.`,
    `Linux is free — if your time is worth nothing.`
  ];

  const LINUXDEVOPS_QUIZ_QUESTIONS = [
    { q:`What does "pwd" print?`, options:[`Your username`,`The current working directory`,`The system's uptime`,`A list of running processes`], correct:1, why:`pwd stands for "print working directory" — it shows exactly where you are in the filesystem right now.` },
    { q:`Which command lists files including hidden ones, with permissions and sizes?`, options:[`ls`,`ls -la`,`find`,`cat`], correct:1, why:`-l gives the long format (permissions, owner, size); -a shows hidden files starting with a dot.` },
    { q:`What does "chmod +x deploy.sh" do?`, options:[`Deletes the file`,`Makes the file executable`,`Changes the file's owner`,`Compresses the file`], correct:1, why:`chmod changes permissions; +x adds execute permission so the script can actually be run.` },
    { q:`In "chmod 755 file.sh", what does the first digit (7) represent?`, options:[`Group permissions`,`Others' permissions`,`Owner's permissions`,`The file size`], correct:2, why:`The three digits are owner, group, others, in that order — 7 (read+write+execute) is the owner's.` },
    { q:`Which command changes both the user and group that own a file?`, options:[`chmod`,`chown`,`chgrp`,`sudo`], correct:1, why:`chown user:group file changes ownership — chmod only changes permissions, not who owns the file.` },
    { q:`What does "df -h" show?`, options:[`A live list of currently running processes and their CPU usage`,`Disk space usage in human-readable sizes`,`How much RAM and swap memory the system currently has in use`,`Which network ports and connections are currently active`], correct:1, why:`df -h reports how full each mounted filesystem is, with sizes in KB/MB/GB instead of raw bytes.` },
    { q:`"df -h" shows 95% full, but nothing in the suspect folder looks unusually large. What's the likely cause?`, options:[`The df command itself is broken and needs a reinstall`,`A process is holding a deleted file open`,`The disk hardware has physically failed and needs replacing`,`du silently requires sudo to see the full picture, and failed quietly`], correct:1, why:`A deleted-but-still-open file keeps consuming space until the process holding it closes or restarts — find it with lsof | grep deleted.` },
    { q:`Which command shows how much space a specific folder is using?`, options:[`df -h`,`free -h`,`du -sh <folder>`,`top`], correct:2, why:`du -sh sums up a folder's contents — df -h only shows whole-filesystem usage.` },
    { q:`What does "free -h" display?`, options:[`Free disk space`,`RAM and swap usage`,`Free CPU cores`,`Free network bandwidth`], correct:1, why:`free -h shows total, used, and available memory (RAM) and swap, in human-readable units.` },
    { q:`Which command gives a live, constantly refreshing view of CPU and memory per process?`, options:[`ps aux`,`top`,`ls -la`,`cat`], correct:1, why:`top refreshes every few seconds and ships on essentially every Linux box — the first tool to reach for when a server "feels slow."` },
    { q:`What's the main difference between "ps aux" and "top"?`, options:[`They're just two different names for the exact same underlying tool`,`ps is a one-time snapshot, top is live and continuously updating`,`ps only works when run with root or sudo privileges`,`top can only show CPU usage and has no visibility into memory at all`], correct:1, why:`ps gives a single parseable snapshot (great for scripts); top keeps refreshing live on screen.` },
    { q:`What does "kill -9 <pid>" do differently from a plain "kill <pid>"?`, options:[`Nothing really — both send the exact same signal to the process`,`Sends SIGKILL, force-terminating with no cleanup`,`It only pauses the process temporarily instead of stopping it`,`It restarts the process fresh instead of terminating it`], correct:1, why:`Plain kill sends SIGTERM (a polite shutdown request); -9 sends SIGKILL, enforced instantly by the kernel with zero chance for cleanup.` },
    { q:`Why try "kill" (SIGTERM) before "kill -9" (SIGKILL)?`, options:[`Because kill -9 is technically slower to execute than a plain kill`,`SIGTERM lets the process shut down cleanly, closing files and finishing work first`,`Because kill -9 is known to silently fail on most distributions`,`Because there's no real practical difference between the two`], correct:1, why:`SIGKILL bypasses the process entirely — no cleanup, which can corrupt open files or leave transactions half-done.` },
    { q:`What is a "zombie" process?`, options:[`A process that's consuming 100% of the CPU and never yielding`,`A finished child process whose parent hasn't read its exit status yet`,`A process that has no assigned owner because its user was deleted`,`A process stuck looping forever and never reaching its exit condition`], correct:1, why:`The kernel keeps a zombie's exit info until the parent calls wait() to collect it — you can't kill a zombie directly since it's already dead.` },
    { q:`How do you fix a buildup of zombie processes?`, options:[`Send it a kill -9 signal directly to force it to terminate`,`Reboot the entire server just to clear the process table`,`Kill (or fix) the parent process so init can reap the orphans`,`Change its file permissions to 777 so the kernel can clean it up`], correct:2, why:`You can't kill something already dead — killing the parent lets init (PID 1) adopt and clean up the orphaned children.` },
    { q:`What does "nohup mycommand &" accomplish?`, options:[`Runs the command with a higher CPU scheduling priority`,`Runs the command in the background, surviving terminal/SSH disconnect`,`Silently discards the command's output instead of showing it`,`Delays running the command until a scheduled time tomorrow`], correct:1, why:`nohup ignores the hangup signal sent when your session closes, and & backgrounds it — but it won't survive a reboot, unlike a systemd service.` },
    { q:`Which command shows which process is using network port 8080?`, options:[`ping 8080`,`sudo lsof -i :8080`,`curl 8080`,`chmod 8080`], correct:1, why:`lsof -i :8080 (or ss -tulnp | grep 8080) reveals exactly which PID and process own that port.` },
    { q:`Why might the PID column be blank when checking a port without sudo?`, options:[`It's a known bug in lsof on certain kernel versions`,`You can't see other users' processes without elevated privileges — a security feature`,`It means the port doesn't actually exist on this machine`,`lsof requires a graphical desktop environment to show that`], correct:1, why:`Linux hides process-ownership details from other users by design; sudo reveals it because you're now privileged.` },
    { q:`What do the flags in "ss -tulpn" mean?`, options:[`Nothing, they're arbitrary`,`TCP, UDP, listening, process, numeric`,`Text, URL, log, path, network`,`Terminal, user, local, port, name`], correct:1, why:`-t TCP, -u UDP, -l listening sockets, -p process info, -n numeric ports instead of resolving service names.` },
    { q:`Which command checks if a remote host is reachable over the network?`, options:[`curl`,`ping`,`ssh`,`grep`], correct:1, why:`ping sends ICMP echo requests and reports whether — and how fast — the host responds. The cheapest first network check.` },
    { q:`What does "curl -I https://example.com" do?`, options:[`Downloads the entire page, including the full HTML body`,`Fetches only the HTTP response headers`,`Sends a request that deletes the resource at that URL`,`Installs the curl tool itself if it isn't already present`], correct:1, why:`-I sends a HEAD request and shows just the headers (like the status code) — a fast way to check if an endpoint is healthy.` },
    { q:`What's the difference between a hard link and a symbolic (soft) link?`, options:[`They're functionally identical, just with two different historical names`,`A hard link is a second name for the same inode; a soft link is a separate file pointing to a path`,`Soft links are always faster to access than hard links, in every case`,`Hard links can cross between filesystems while soft links cannot`], correct:1, why:`Delete the original file: the hard link still works (same underlying data), but a soft link starts pointing at nothing and dangles.` },
    { q:`Can you create a hard link across two different filesystems (e.g. two different disks)?`, options:[`Yes, hard links can always be created across any two filesystems`,`No — hard links share inodes, which are filesystem-specific`,`Only if you run the command with sudo or root privileges`,`Only for plain text files — binary files can't be hard-linked`], correct:1, why:`Inodes only exist within a single filesystem, so a hard link can't point at one on a different disk. Soft links can, since they just store a path.` },
    { q:`What does "ln -s release-v23 current" create?`, options:[`A full copy of the release-v23 folder, saved under the name current`,`A symbolic link named current pointing at release-v23`,`A backup file containing a snapshot of the release folder`,`A compressed archive bundling up the contents of release-v23`], correct:1, why:`This is the classic instant-rollback trick: repoint the "current" symlink at an older release and the rollback is done — zero file copying.` },
    { q:`What does ">" do when you run "command > file.txt"?`, options:[`Appends the command's output onto the end of the existing file`,`Overwrites the file with the command's output`,`Redirects only the error messages, leaving normal output untouched`,`Pipes the command's output directly into another command`], correct:1, why:`> always replaces the file's entire previous contents — this is why using > instead of >> on a cron log wipes history every single run.` },
    { q:`What's the difference between ">" and ">>"?`, options:[`There's no real difference — they behave exactly the same way`,`> overwrites, >> appends to the end`,`The double form >> is reserved specifically for redirecting errors`,`The single > is simply a faster version of the same redirect`], correct:1, why:`>> preserves what's already in the file and adds new output after it — the safe choice for anything that logs repeatedly, like cron jobs.` },
    { q:`What does "2>" redirect?`, options:[`Standard input — whatever is being typed into the command`,`Standard output — the command's normal, non-error output`,`Standard error (stderr) only`,`Both the standard output and standard error at the same time`], correct:2, why:`File descriptor 2 is stderr — "2> file.txt" sends only error messages there, leaving normal output on the screen.` },
    { q:`What does "command > file 2>&1" do?`, options:[`Redirects only the error stream, leaving normal output on the screen`,`Redirects stdout to the file, then makes stderr go wherever stdout is now going (the same file)`,`Doesn't redirect anything, because the syntax is actually invalid`,`Deletes the target file first, before any output is written`], correct:1, why:`Order matters: this sends stdout to the file first, then points stderr at the same destination — "2>&1 > file" would NOT work the same way.` },
    { q:`What does "echo $?" show right after a command runs?`, options:[`Prints the previous command's actual text output all over again`,`The exit code of the last command (0 = success)`,`Prints today's date, formatted using the system's default locale`,`Prints the full path of the directory you're currently in`], correct:1, why:`0 always means success; any other number means failure — this is exactly what && and || check behind the scenes.` },
    { q:`What's the difference between "&&" and "||" in a shell command chain?`, options:[`They're interchangeable and can always be swapped for one another`,`&& runs the next command only on success, || runs the next command only on failure`,`&& is only valid inside loops, || is only valid inside if-statements`,`|| always executes first, regardless of where it appears`], correct:1, why:`"make && make install" only installs if the build succeeded. "cmd || echo failed" only prints the fallback if cmd failed.` },
    { q:`What does a single "|" do between two commands?`, options:[`Acts as a logical OR between the two commands, like in programming`,`Runs both commands completely independently, with no connection`,`Pipes the first command's output as the second command's input`,`Comments out everything after it, so the second command never runs`], correct:2, why:`"cat file | grep error" feeds file's contents directly into grep — this is how DevOps one-liners chain filtering tools together.` },
    { q:`What does appending "&" to the end of a command do?`, options:[`Runs the command with elevated root privileges automatically`,`Runs it in the background and returns the terminal immediately`,`Immediately cancels the command before it has a chance to run`,`Repeats the command forever in an infinite loop until stopped`], correct:1, why:`The shell is freed up right away while the command keeps running behind it — but confusing this with && has caused real production incidents.` },
    { q:`"grep -i \"error\" app.log" — what does the -i flag do?`, options:[`Inverts the match, showing only lines that do NOT contain the pattern`,`Makes the search case-insensitive`,`Searches recursively through every subdirectory automatically`,`Adds line numbers to the beginning of every matching line`], correct:1, why:`-i means ERROR, error, and Error all match — useful since log severity casing isn't always consistent.` },
    { q:`What is "awk" best used for?`, options:[`Only useful for printing a file's raw contents to the screen`,`Column-aware text processing — extracting, filtering, and transforming fields`,`Compressing and archiving files to save disk space`,`Creating and managing user accounts on the system`], correct:1, why:`"awk '{print $1, $7}'" pulls out just columns 1 and 7 — it's a small but genuinely full scripting language, not just a print tool.` },
    { q:`What does "sed -i 's/old/new/g' file.txt" do?`, options:[`Deletes every occurrence of the word "old" from the file entirely`,`Replaces every occurrence of "old" with "new", editing the file in place`,`Only previews the changes without writing anything to disk`,`Renames the file itself, without touching its contents`], correct:1, why:`-i edits the file directly, and the trailing g means replace ALL occurrences on each line, not just the first.` },
    { q:`What is the purpose of "journalctl -u nginx -n 50"?`, options:[`Immediately restarts the nginx service and reloads its config`,`Shows the last 50 log lines for the nginx systemd service`,`Installs the nginx package fresh from the package manager`,`Permanently deletes all of nginx's stored log history`], correct:1, why:`journalctl is systemd's log tool; -u filters to one specific service, -n limits how many recent lines to show.` },
    { q:`A service shows "failed" in "systemctl status". What's the fastest next step?`, options:[`Reboot the entire server to see if the problem clears itself`,`Reinstall the service completely from scratch, right away`,`Run journalctl -u <service> to read the actual error`,`Delete the service entirely and hope the problem goes away`], correct:2, why:`The status output gives a hint, but journalctl shows the real error — like a missing dependency or bad config — that caused the failure.` },
    { q:`Why does a systemd-managed service survive a reboot, but a "nohup" background process doesn't?`, options:[`They're actually the exact same underlying mechanism, just with two different historical names`,`systemd re-starts registered services automatically on boot; nohup only detaches from your terminal session`,`nohup is simply a faster, more lightweight version of systemd with less overhead`,`systemd requires significantly more RAM and disk space just to keep one process alive`], correct:1, why:`systemd is the init system itself and manages the full service lifecycle including startup on boot — nohup is just a quick manual workaround.` },
    { q:`What does "crontab -e" do?`, options:[`Immediately and permanently deletes every scheduled cron job`,`Opens your personal list of scheduled jobs for editing`,`Runs every scheduled cron job immediately, all at once`,`Lists all currently running processes on the system`], correct:1, why:`It opens (or creates) your crontab file in an editor, where each line schedules one recurring command.` },
    { q:`In cron syntax "*/5 9-17 * * 1-5", what does this schedule mean?`, options:[`Runs the job exactly once a day, at 5:00 in the afternoon`,`Every 5 minutes, 9am–5pm, Monday–Friday`,`Runs the job every 5 hours, all seven days of the week`,`Runs the job just once per week, on one fixed day`], correct:1, why:`The five fields are minute, hour, day-of-month, month, day-of-week — this targets business hours only, Monday through Friday.` },
    { q:`Why do cron jobs often fail even though the same command works fine typed manually?`, options:[`Cron itself is fundamentally broken on most modern distributions and needs reinstalling`,`Cron runs with a minimal environment and often lacks the full $PATH your interactive shell has`,`Cron is simply incapable of running any kind of shell script under any circumstance`,`Cron only actually executes scheduled jobs on one day a week, Sundays specifically`], correct:1, why:`Cron doesn't load your shell's profile, so tools like kubectl or python may not be found unless you use absolute paths or source the environment.` },
    { q:`What does "sudo usermod -aG docker deploy" do?`, options:[`Permanently deletes the deploy user account from the system`,`Adds the deploy user to the docker group, granting it Docker's permissions`,`Removes the deploy user from every group they belong to`,`Renames the deploy user's account to simply be called docker`], correct:1, why:`This is the actual fix for "permission denied while trying to connect to the Docker daemon socket" — a very common first-week error.` },
    { q:`What is the "shebang" line at the top of a shell script (#!/bin/bash) for?`, options:[`Just a harmless comment that has no real effect on execution`,`It tells the OS which interpreter should execute the rest of the file`,`Sets the file's read, write, and execute permissions directly`,`Imports and runs every other script found in the same folder`], correct:1, why:`Without a correct shebang as the very first line, the system won't know whether to run the file with bash, python, or something else.` },
    { q:`In a shell script, what does "$1" refer to?`, options:[`Always evaluates to the script's own filename, no matter what`,`The first command-line argument passed to the script`,`Refers to the very first line of code written in the script`,`Holds the process ID number the script is currently running under`], correct:1, why:`Running "./deploy.sh myapp production" makes $1 equal "myapp" and $2 equal "production" inside the script.` },
    { q:`What does "set -euo pipefail" do at the top of a shell script?`, options:[`Nothing at all — it's purely optional decoration that has no real effect whatsoever`,`Makes the script exit immediately on any error, treat unset variables as errors, and catch failures inside pipes`,`Sets a handful of environment variables for the script to reference later on`,`Makes the script run measurably faster by skipping unnecessary safety checks`], correct:1, why:`Without this, a script can keep running after something already failed silently — this line is the biggest habit separating safe scripts from dangerous ones.` },
    { q:`What does "$(command)" do inside a shell script?`, options:[`Comments out the command entirely so it never actually runs`,`Runs the command and substitutes its output directly into the surrounding string`,`Permanently deletes the command from the script file`,`Schedules the command to run later instead of immediately`], correct:1, why:`Command substitution — e.g. "now=$(date)" — lets a script capture live data like the current date or a git branch name.` },
    { q:`What does "idempotent" mean for a DevOps script?`, options:[`Means the script automatically runs faster with each execution`,`Running the script multiple times produces the same end result as running it once`,`Means the script can never be interrupted once it starts`,`Means the script automatically deletes itself after it finishes`], correct:1, why:`A non-idempotent script that blindly appends to a config file, run three times, leaves three duplicate entries — always check state before acting.` },
    { q:`What's the safest way to add a line to /etc/hosts only if it isn't already there?`, options:[`echo line >> /etc/hosts every time, no checks needed`,`grep -q "line" /etc/hosts || echo "line" >> /etc/hosts`,`rm /etc/hosts first`,`cat /etc/hosts > /etc/hosts`], correct:1, why:`This checks whether the line already exists first, and only appends if it's missing — the idempotent pattern that avoids duplicate entries.` },
    { q:`What's the correct order in the Linux boot process?`, options:[`The order is completely interchangeable and genuinely doesn't matter at all`,`BIOS/UEFI checks hardware and finds the bootloader, GRUB hands off to the kernel, the kernel then starts systemd`,`GRUB actually runs after the kernel has already fully started and booted`,`UEFI is a full, direct replacement for systemd and handles all service startup`], correct:1, why:`The order is: BIOS/UEFI (hardware check) → GRUB (bootloader, picks a kernel) → kernel (mounts root filesystem) → systemd (PID 1, starts all services).` },
    { q:`On a modern systemd-based distro, why might "tail -f /var/log/syslog" show nothing useful for a failing service?`, options:[`The syslog file itself is always completely broken on every modern distro`,`Services managed by systemd log to the journal first — journalctl is the authoritative source, not syslog`,`The tail command fundamentally doesn't work on any kind of log file at all`,`You always need full root access just to read any log file on the system`], correct:1, why:`journalctl -u <service> is where systemd actually writes service logs — syslog may be empty or incomplete on these systems.` }
  ];
